design.css:
/* Theme API 9: every rule below reads a theme setting from <html>. */
[data-part="row.title"] { color: var(--theme-setting-heading); }
:scope[data-theme-setting-corners="square"] [data-part="card.art"] { border-radius: 0 !important; }
:scope[data-theme-setting-corners="round"] [data-part="card.art"] { border-radius: 1.25rem !important; }
:scope[data-theme-setting-card-titles="off"] [data-part="card.title"] { display: none; }
